for n,x in libs.items():
 z=pd.concat([f.stack().rename('f'),x.stack().rename('x')],axis=1).dropna(); print('corr',n,z.f.corr(z.x),len(z))
# coverage
print('coverage',f.notna().sum().sum()/f.size)

