  z=pd.concat([f.iloc[i].rename('f'),(close.iloc[i+h]/close.iloc[i]-1).rename('r')],axis=1).dropna()
  if len(z)>=8 and z.f.nunique()>1 and z.r.nunique()>1: rows.append(z.f.corr(z.r,method='spearman'))
