a=np.asarray(ics); print('dates',len(a),'avgN',np.mean(ns),'coverage',np.sum(ns)/(len(ns)*15),'IC',a.mean(),'ICIR',a.mean()/a.std(ddof=1),'hit',np.mean(a>0),'turn',np.mean(turns))
