    vv={}
    for s,p in px.items():
      if t not in p.index: continue
      h=p.loc[:t]
      if kind=='rev5' and len(h)>=6: vv[s]=-float(h.iloc[-1]/h.iloc[-6]-1)
      if kind=='lead5' and len(h)>=6:
